settings.custom_css:
#b2b-forma input{
    padding:15px;
}
#b2b-forma select{
    padding:15px;
}

/* Scope to this form only */
#b2b-forma .elementor-field-group.elementor-field-type-upload {
  position: relative;
}

/* Make the input look like a nice box */
#b2b-forma .elementor-field-type-upload input[type="file"]{
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  padding: 20px 0px 20px 20px; /* right padding for the icon */
  background: #fff;
  font: inherit;
  color: transparent;              /* hide default filename text */
  cursor: pointer;
}

/* Hide the ugly native button across browsers */
#b2b-forma .elementor-field-type-upload input[type="file"]::file-selector-button{ display:none; }
#b2b-forma .elementor-field-type-upload input[type="file"]::-webkit-file-upload-button{ visibility:hidden; }
#b2b-forma .elementor-field-type-upload input[type="file"]::-ms-browse{ display:none; }

/* Placeholder or selected filename (set via data-filename in JS) */
#b2b-forma .elementor-field-type-upload { --placeholder: "Please upload a file"; }
#b2b-forma .elementor-field-type-upload::after{
  content: var(--placeholder);
  position: absolute;
  left: 16px;
  top: 60%;
  transform: translateY(-50%);
  color: #9ca3af;
  pointer-events: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 64px); /* leave room for icon */
}

/* When a file is chosen, show its name instead of the placeholder */
#b2b-forma .elementor-field-type-upload[data-filename]::after{
  content: attr(data-filename);
  color: #111827;
}

/* Right-side upload icon */
#b2b-forma .elementor-field-type-upload::before{
  content: "";
  position: absolute;
  right: 16px;
  top: 60%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  opacity: .45;
  background-repeat: no-repeat;
  background-position: center;
  background-size: 22px 22px;
  /* simple inline SVG icon */
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="%23999" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>');
}
